// Des: Tests for M16: vendor learning, honeypot links, truncation, poison, OCR adapter
// Flo: replayed outcomes > order shifts; hub page > only real link followed; helpers on samples
// I/O: mock server + db > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const hits = @import("ru-hits-lear.zig"); const trap = @import("pa-trap-dete.zig"); const ocrz = @import("nt-ocrz-exte.zig"); const walk = @import("ru-page-walk.zig"); const inde = @import("st-page-inde.zig"); const mock = @import("te-mock-serv.zig"); const sqli = @import("st-stor-sqli.zig"); const builtin = @import("builtin");
const allo = std.testing.allocator;
fn memdb() !struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: sqli.Db } { const tmpz = std.testing.tmpDir(.{}); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); return .{ .tmpz = tmpz, .dirz = dirz, .dbzz = try inde.pageOpen(allo, std.testing.io, dirz) }; }
test "replayed results move the winner first; cheaper winner beats a dearer one; unsampled stays in config order" { var db = try memdb(); defer { db.dbzz.close(); allo.free(db.dirz); db.tmpz.cleanup(); } var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const base = [_][]const u8{ "deco", "zenr", "brig" }; const now: i64 = 1_000_000_000_000; var idx: usize = 0; while (idx < 3) : (idx += 1) { try hits.hitsRec(&db.dbzz, "a.test", "deco", 2, false, 0, 0, now); try hits.hitsRec(&db.dbzz, "a.test", "zenr", 2, true, 1, 1000, now); } const ord = try hits.hitsOrde(&db.dbzz, aren.allocator(), "a.test", &base, 2, now); try std.testing.expectEqualStrings("zenr", ord[0]); try std.testing.expectEqualStrings("brig", ord[1]); try std.testing.expectEqualStrings("deco", ord[2]); idx = 0; while (idx < 3) : (idx += 1) { try hits.hitsRec(&db.dbzz, "b.test", "deco", 3, true, 2, 3000, now); try hits.hitsRec(&db.dbzz, "b.test", "zenr", 3, true, 5, 9000, now); } const ord2 = try hits.hitsOrde(&db.dbzz, aren.allocator(), "b.test", &base, 3, now); try std.testing.expectEqualStrings("deco", ord2[0]); try std.testing.expectEqualStrings("zenr", ord2[1]); const fresh = try hits.hitsOrde(&db.dbzz, aren.allocator(), "c.test", &base, 2, now); try std.testing.expectEqualStrings("deco", fresh[0]); }
test "learning resets after 30 days" { var db = try memdb(); defer { db.dbzz.close(); allo.free(db.dirz); db.tmpz.cleanup(); } var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const base = [_][]const u8{ "zenr", "deco" }; const now: i64 = 1_000_000_000_000; try hits.hitsRec(&db.dbzz, "a.test", "zenr", 2, false, 0, 0, now); try hits.hitsRec(&db.dbzz, "a.test", "zenr", 2, false, 0, 0, now); const fresh = try hits.hitsOrde(&db.dbzz, aren.allocator(), "a.test", &base, 2, now); try std.testing.expectEqualStrings("deco", fresh[0]); const aged = try hits.hitsOrde(&db.dbzz, aren.allocator(), "a.test", &base, 2, now + 31 * 86400000); try std.testing.expectEqualStrings("zenr", aged[0]); }
test "link finder flags every kind of honeypot, keeps real links" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const page = "<a href=\"/real\">ok</a><a href=\"/h1\" style=\"display:none\">x</a><a href=\"/h2\" hidden>x</a><div style=\"opacity:0\"><span><a href=\"/h3\">x</a></span></div><a href=\"/after\">ok2</a><a href=\"/h4\" rel=\"nofollow\">x</a><a href=\"/h5\" class=\"my-honeypot\">x</a><a href=\"/h6\" aria-hidden=\"true\" tabindex=\"-1\">x</a><a href=\"http://other.test/x\">off</a>"; const got = try trap.linkFind(aren.allocator(), "http://h.test/p", page); var real: usize = 0; var traps: usize = 0; for (got) |lk| { if (lk.trap) { traps += 1; } else { real += 1; } } try std.testing.expectEqual(@as(usize, 2), real); try std.testing.expectEqual(@as(usize, 6), traps); for (got) |lk| { if (std.mem.eql(u8, lk.urlz, "http://h.test/after")) try std.testing.expect(!lk.trap); } }
test "walk --follow: honeypot links are never fetched, real link is" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wlk = walk.Walk.init(allo, std.testing.io, .{}, &dbzz, dirz, true); defer wlk.deinit(); wlk.gapz = 0; wlk.base = 0; wlk.foll = 10; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const hub = try aren.allocator().dupe(u8, srv.urlOf(&buf, "/hub")); _ = try wlk.walkSeed(&.{hub}); const sum = try wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 2), sum.done); try std.testing.expectEqual(@as(u32, 4), sum.trap); for ([_][]const u8{ "/p3", "/p9", "/p8", "/p7" }) |pth| { var b2: [64]u8 = undefined; try std.testing.expect(try inde.pageGet(&dbzz, aren.allocator(), srv.urlOf(&b2, pth)) == null); } var b3: [64]u8 = undefined; try std.testing.expect(try inde.pageGet(&dbzz, aren.allocator(), srv.urlOf(&b3, "/p1")) != null); }
test "walk without --follow queues nothing extra" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var srv: mock.Mock = undefined; try srv.start(std.testing.io); defer srv.halt(); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wlk = walk.Walk.init(allo, std.testing.io, .{}, &dbzz, dirz, true); defer wlk.deinit(); wlk.gapz = 0; wlk.base = 0; var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const hub = try aren.allocator().dupe(u8, srv.urlOf(&buf, "/hub")); _ = try wlk.walkSeed(&.{hub}); const sum = try wlk.walkRun(null); try std.testing.expectEqual(@as(u32, 1), sum.done); try std.testing.expectEqual(@as(u32, 0), sum.trap); }
test "truncated page and poisoned record are caught" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expect(trap.trunChek("<html><head><title>x</title></head><body><p>cut off mid")); try std.testing.expect(!trap.trunChek("<html><body><p>complete page text</p></body></html>")); const req = [_][]const u8{ "name", "price" }; try std.testing.expect((try trap.poisChek(aren.allocator(), "{\"name\":\"Widget\",\"price\":12}", &req)) == null); try std.testing.expectEqualStrings("price", (try trap.poisChek(aren.allocator(), "{\"name\":\"Widget\",\"price\":null}", &req)).?); try std.testing.expectEqualStrings("name", (try trap.poisChek(aren.allocator(), "[{\"price\":3}]", &req)).?); try std.testing.expect((try trap.poisChek(aren.allocator(), "{broken", &req)) != null); }
test "OCR adapter: off by default, a stand-in tool returns its output, a missing tool is a typed error" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); try std.testing.expectError(error.NoOcr, ocrz.ocrRun(aren.allocator(), std.testing.io, "", "x", dirz)); try std.testing.expectError(error.OcrFail, ocrz.ocrRun(aren.allocator(), std.testing.io, "/no/such/tool", "x", dirz)); const exe: []const u8 = if (builtin.os.tag == .windows) "C:\\Windows\\System32\\more.com" else "/bin/cat"; const got = ocrz.ocrRun(aren.allocator(), std.testing.io, exe, "scanned words here", dirz) catch return; try std.testing.expectEqualStrings("scanned words here", got); }
